script:
const banner = root_element.querySelector(".setup-banner");
const widget = root_element.host.closest(".widget");
if (widget) widget.style.display = "none";

frappe
  .xcall("central.billing.api.admin.accounting.get_manual_setup_gaps")
  .then((gaps) => {
    if (!gaps.length) return;
    const list = banner.querySelector(".setup-gaps");
    for (const gap of gaps) {
      const item = document.createElement("li");
      item.textContent = gap.detail;
      list.appendChild(item);
    }
    banner.hidden = false;
    if (widget) widget.style.display = "";
  });

style:
.setup-banner {
  padding: var(--padding-md);
  border-radius: var(--border-radius-md);
  background: var(--bg-orange);
  color: var(--text-on-orange);
}
.setup-title {
  font-weight: var(--weight-semibold);
}
.setup-gaps {
  margin: var(--margin-xs) 0;
  padding-left: var(--padding-lg);
}
.setup-banner a {
  color: inherit;
  text-decoration: underline;
}
